private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null)
        throw new IllegalArgumentException("Cannot rotate right a null node or a node without a left child.");

    TreeNode<T> rightChild = node.left;
    node.left = rightChild.right;
    rightChild.parent = node.parent;
    rightChild.right = node;
    node.parent = rightChild;

    // Update the heights of the affected nodes
    node.setHeight(Math.max(node.left.getHeight(), node.right.getHeight()) + 1);
    rightChild.setHeight(node.getHeight() + 1);

    return rightChild;
}

