            if (i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
                return i + 2;
            }
            return i;
        }
    }
    return -1; // No \r\n found, handle as needed
}

private int parseEndOfLine(String headerPart, int end) {
    for (int i = end - 1; i >= 0; i--) {
        if (headerPart.charAt(i) == '\n') {
            return i;
        }
        if (headerPart.charAt(i) == '\r') {
            if (i > 0 && headerPart.charAt(i - 1) == '\n') {
                return i;
            }
            return end;
        }
    }
    return -1; // No newline found, end of the headers is reached
}

