}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] encodedMessage = schema.encode(message);
    byte[] length = encodeLength(encodedMessage.length);

    ByteBuf buf = Unpooled.buffer(encodedMessage.length + 2);
    buf.writeBytes(length);
    buf.writeBytes(encodedMessage);

    out.write(buf.nioBuffer());
    return encodedMessage.length + 2;
}

