    public String toString() {
        return "TimeRange{" +
                "start=" + start +
                ", end=" + end +
                '}';
    }
}



    private static final long FETCH_DATA_DURATION = 30 * 60; // 30 minutes in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        // Calculate the smallest duration that the start and end times can differ
        long smallestDuration = Math.min(FETCH_DATA_DURATION, end - start);

        // Calculate the number of time ranges required
        int numRanges = ((end - start) + smallestDuration - 1) / smallestDuration;

        if (numRanges == 0) {
            // If there's no time difference greater than 30 minutes, create a single range
            timeRanges.add(new TimeRange(Instant.ofEpochMilli(start), Instant.ofEpochMilli(end)));
        } else {
            // Create multiple time ranges
            for (int i = 0; i < numRanges; i++) {
                Instant startTime = Instant.ofEpochMilli(start + i * smallestDuration);
                Instant endTime = Math.min(end, startTime.plusMillis(smallestDuration));
                timeRanges.add(new TimeRange(startTime, endTime));
            }
        }

        return timeRanges;
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end && start + FETCH_DATA_DURATION < end) {
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION));
        start += FETCH_DATA_DURATION;
    }
    // Add any remaining time interval
    if (start < end) {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the range to ensure start and end are within FETCH_DATA_DURATION
    long duration = FETCH_DATA_DURATION;
    long minStart = Math.max(start, end - duration);
    long maxEnd = Math.min(end + duration, Long.MAX_VALUE);

    // Add a new time range within the calculated limits
    timeRanges.add(new TimeRange(minStart, maxEnd));

    return timeRanges;
}

private static final long FETCH_DATA_DURATION = 60 * 60 * 1000;

List<TimeRange> function(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    long duration = Math.abs(end - start);
    long step = Math.min(FETCH_DATA_DURATION, duration / 10); // Insure each time range is small enough
    for (long i = start; i <= end; i += step) {
        result.add(new TimeRange(i, Math.min(i + step, end)));
    }
    return result;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    long fetchDataDuration = 1000L; // Make sure the duration is not too short

    if (end - start > fetchDataDuration) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = currentStart + fetchDataDuration - 1; // Start with FetchDataDuration slot

        while (currentStart <= end) {
            TimeRange timeRange = new TimeRange(currentStart, currentEnd);
            timeRanges.add(timeRange);
            currentStart = currentEnd + 1;
            currentEnd = currentStart + fetchDataDuration - 1;
        }

        return timeRanges;
    } else {
        List<TimeRange> timeRanges = new ArrayList<>();
        timeRanges.add(new TimeRange(start, end));
        return timeRanges;
    }
}

