public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the new time bucket by shifting the century decade, quarter, and month
    return timeBucket + (dayStep * 1460) - (dayStep * (24 / (int) dayStep));
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket cannot be negative.");
    }

    int year = (int) timeBucket / 10000;
    int month = (int) timeBucket / 1000 % 100;
    int day = (int) timeBucket % 100;

    if (year < 1000) {
        year += 2000;
    }

    int reformattedDay = (day / dayStep) * dayStep;
    long reformattedTimeBucket = year * 10000 + month * 100 + reformattedDay;

    return reformattedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long startTime = timeBucket;
    while (timeBucket > 0) {
        timeBucket -= dayStep;
        startTime += 1;
    }
    long startTimeCompressed = startTime / dayStep * dayStep;
    long lastDay = timeBucket % dayStep;
    while (lastDay > 0) {
        lastDay -= dayStep;
        startTimeCompressed += 1;
    }
    return startTimeCompressed;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTime = timeBucket / (1000 * 60 * 60 * 24 / dayStep);
    return compressedTime * (1000 * 60 * 60 * 24 / dayStep);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep cannot be zero or negative");
    }
    return (timeBucket + dayStep - 1) / dayStep;
}

