public static LinkedBuffer writeUTF8(CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || lb == null) {
        throw new NullPointerException("Character sequence or LinkedBuffer cannot be null");
    }

    synchronized (lb) {
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);

            if (c > 127) {
                int index = (c & 192) | ((c & 64) >> 2);
                lb.append((byte) index);
                index = (c & 32) | ((c & 4)) >> 1;
                lb.append((byte) index);
                index = c & 1;
                lb.append((byte) index);

                if (index >= 64 && index < 96 && c > 255) {
                    throw new RuntimeException("UTF-8 string too long");
                }
            } else {
                lb.append((byte) c);
            }
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if (str == null || lb == null) {
        throw new IllegalArgumentException("Invalid input: str must not be null and lb must not be null");
    }
    for (int i = 0; i < str.length(); i++) {
        int b = (int) str.charAt(i);
        if (b >= 0 && b < 128) {
            lb.write(true, (byte) b);
        } else {
            if (b < 1280) { // 16-bit surrogates start from 0xD800 and end at 0xDFFF
                lb.write(true, (byte) (0xE0 | (b >> 10)));
                lb.write(true, (byte) (0x80 | ((b & 0x3F) >> 2)));
            } else { // 32-bit UTF-8 sequence starts from 0x10000 and ends at 0x10FFFF
                lb.write(true, (byte) (0xF0 | (b >> 12)));
                lb.write(true, (byte) (0x80 | ((b & 0x3F) >> 6)));
                lb.write(true, (byte) (0x80 | ((b & 0x7F))));
            }
        }
    }
    return lb;
}

