 */
public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double width = box.getWidth();
    double splitPoint = width / 2;

    Box2D leftBox = new Rectangle2D.Double(box.getX(), box.getY(), splitPoint, box.getHeight());
    Box2D rightBox = new Rectangle2D.Double(box.getX() + splitPoint, box.getY(), width - splitPoint, box.getHeight());

    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double width = box.getWidth();
    // Calculate the position for each child box
    double position = width / 2;

    // Split the box into two boxes
    Box2D leftBox = new Box2D(box.getX(), box.getY(), position, box.getHeight());
    Box2D rightBox = new Box2D(position, box.getY(), box.getWidth() - position, box.getHeight());

    return Pair.create(leftBox, rightBox);
}

/**
 * Split a box along the x axis into two equal boxes.
 * @param box the box to split
 * @return a pair with the two resulting boxes
 */
public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint of the box
    double midX = box.getCenterX();
    double width = box.getWidth();
    Box2D leftBox = new Box2D(midX - width / 2, box.getY(), width / 2, box.getHeight());
    Box2D rightBox = new Box2D(midX + width / 2, box.getY(), width / 2, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

/**
