 * @param box the box to split
 * @return a pair with the two resulting boxes
 */
public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double x1 = box.getX();
    double x2 = box.getX() + box.getWidth();
    int splitX = (int) (x1 + x2) / 2;
    return new Pair<>(new Box2D(new Point2D.Double(x1, box.getY()), new Dimension2D.Double(splitX - x1, box.getHeight())),
                     new Box2D(new Point2D.Double(splitX, box.getY()), new Dimension2D.Double(x2 - splitX, box.getHeight())));
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
