public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int contentSize = 0;
    ByteChunk chunk = node.getByteChunk();
    int remainingSize = chunk.getLength();
    while (remainingSize > 0) {
        int bytesWritten = out.write(chunk.getBuffer(), 0, Math.min(remainingSize, 4096));
        contentSize += bytesWritten;
        remainingSize -= bytesWritten;
    }
    return contentSize;
}

public int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    while (node != null) {
        if (node.getData() != null) {
            out.writeInt(node.getData().length);
            out.write(node.getData());
            totalSize += node.getData().length;
        }
        node = node.getNext();
    }

    return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0; // Initialize total content size
    node.resetAndStart(); // Reset the buffer to its starting state
    while (node.hasMoreChunks()) {
        Object[] chunk = node.getNextChunk(); // Get the next complete chunk
        int chunkSize = chunk.length; // Get the size of the current chunk
        totalSize += chunkSize; // Add the size of the current chunk to the total size
        out.write(chunk); // Write the chunk to the output
    }
    node.completeAndClearBuffer(); // Complete and clear the buffer
    return totalSize; // Return the total content size of the buffer
}

int function (DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    // Copy LinkedBuffer content to a byte array
    byte[] buffer = new byte[node.size()];
    for (int i = 0; i < node.size(); i++) {
        buffer[i] = node.get(i);
    }

    // Write the byte array to DataOutput
    out.write(buffer);

    // Return the total content size of the buffer
    return node.size();
}

private int writeOutBufferToDataOutput(OutputBuffer out, LinkedBuffer node, int accumulatedLength) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("Output and node must not be null");
    }

    long nodeSize = node.getSize();

    if (nodeSize > remainingBytes - accumulatedLength) {
        nodeSize = remainingBytes - accumulatedLength;
    }

    try {
        for (int i = 0; i < nodeSize; i++) {
            byte data = node.readByte();
            out.writeByte(data);
            accumulatedLength++;
        }
    } catch (IOException e) {
        throw new IOException("Failed to write from LinkedBuffer to DataOutput", e);
    }

    return accumulatedLength;
}

