private void putAbstractTypes(final int start, final int end) throws TypeMismatchException {
    if (start < 0 || start >= currentFrame.length || end < 0 || end >= currentFrame.length || start >= end) {
        throw new TypeMismatchException("Invalid range for start and end indices");
    }

    for (int i = start; i < end; i++) {
        AbstractTypeMember info = currentFrame[i];
        if (info.getJVMDescription().getSignature() == null) {
            throw new TypeMismatchException("Signature is null for type " + info.getName());
        }

        int tag;
        switch (info.getJVMDescription().getSignature().charAt(0)) {
            case 'B': tag = 1; break;
            case 'C': tag = 2; break;
            case 'D': tag = 3; break;
            case 'F': tag = 4; break;
            case 'I': tag = 5; break;
            case 'J': tag = 6; break;
            case 'S': tag = 7; break;
            case 'V': tag = 9; break;
            case 'Z': tag = 10; break;
            case '[':
                switch (info.getJVMDescription().getSignature().charAt(1)) {
                    case 'B': tag = 1; break;
                    case 'C': tag = 2; break;
                    case 'D': tag = 3; break;
                    case 'F': tag = 4; break;
                    case 'I': tag = 5; break;
                    case 'J': tag = 6; break;
                    case 'S': tag = 7; break;
                    case 'V': tag = 9; break;
                    case 'Z': tag = 10; break;
                    default: throw new TypeMismatchException("Unsupported array type");
                }
                tag |= TypeConstants.ARRAY;
                break;
            case 'L': {
                if (info.getJVMDescription().getSignature().length() == 2) {
                    tag = 9; break; // Java primitive types
                }
                tag = 8; // Reference type
                info.setName(info.getJVMDescription().getSignature().substring(1, info.getJVMDescription().getSignature().length() - 1));
                break;
            }
            default: throw new TypeMismatchException("Unsupported type");
        }

        IUnicodeString name = new BytesUnicodeString(info.getName());
        IUTF8String signature = new BytesUTF8String(info.getJVMDescription().getSignature());
        try {
            stackMapTableEntries[i] = new StackMapTableEntry(tag, name, signature);
        } catch (InvalidUnicodeStringException e) {
            throw new TypeMismatchException("Invalid Unicode string error: " + e.getMessage());
        }
    }
}

