public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("Desired capacity must be greater than or equal to 2");
    }

    int n = desiredCapacity;
    int quotient = nextPowerOfTwo(n >> 1); // The largest power of two less than or equal to n/2
    int prime = quotient * 2 + 1;

    while (!isPrime(prime)) {
        prime += 2; // Skip even numbers (since all primes from 2 are odd)
    }

    return prime;
}

public static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPowerOfTwo(int n) {
    n--;
    n |= n >>> 1;
    n |= n >>> 2;
    n |= n >>> 4;
    n |= n >>> 8;
    n |= n >>> 16;
    n++;
    return n;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be greater than 0");
    }

    int prime = desiredCapacity;
    while (true) {
        int increment = prime > 3 ? 6 : (prime % 2 == 0) ? 4 : 2;
        for (int i = 5; i * i <= prime; i += increment) {
            if (prime % i == 0) {
                prime += increment;
                break;
            }
        }
        if (prime >= desiredCapacity * 1.11 && prime <= desiredCapacity * 12.89) {
            return prime;
        }
    }
}

