public static String trimTrailingWhitespace(String str) {
    if (str == null) return null;

    int length = str.length();
    int trailingIndex = length - 1;

    while (trailingIndex >= 0 && Character.isWhitespace(str.charAt(trailingIndex))) {
        trailingIndex--;
    }

    if (trailingIndex >= 0) {
        return str.substring(0, trailingIndex + 1);
    } else {
        return str;
    }
}

