public static String unescapeJava(String str) throws Exception {
  if (str == null) return null;
  char[] replacements = {"\\n", "\\t", "\\r"};
  String[] replacementsAsStrings = {"\n", "\t", "\r"};
  StringBuilder escapedString = new StringBuilder(str);
  for (int i = 0; i < escapedString.length(); i++) {
    if (escapedString.charAt(i) == '\\') {
      char nextChar = 0;
      if (i + 1 < escapedString.length()) {
        nextChar = escapedString.charAt(i + 1);
      }
      if ((nextChar == 'n') || (nextChar == 't') || (nextChar == 'r')) {
        escapedString.setCharAt(i, replacementsAsStrings[replacements.indexOf(nextChar)]);
        i++;
      }
    }
  }
  return escapedString.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    StringBuilder escapeChar = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (!escapeChar.isEmpty()) {
                char replaceChar = escapeChar.charAt(0);
                if (c == replaceChar) {
                    if (i < str.length() - 1 && str.charAt(i + 1) == '\\') {
                        sb.append(c); // Handle double backslashes
                        i++;
                    } else {
                        sb.append(replaceChar);
                    }
                } else {
                    escapeChar.append(c);
                }
            } else {
                escapeChar.append(c);
            }
        } else if (escapeChar.length() > 0) {
            escapeChar.deleteCharAt(0);
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\\':
                        result.append('\\');
                        break;
                    case 'n':
                        result.append('\n');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case '"':
                        result.append('"');
                        break;
                    case '\'':
                        result.append('\'');
                        break;
                    default:
                        result.append('\\');
                        result.append(nextChar);
                }
                i += 1;
            } else {
                result.append('\\');
