public static String unescapeJava(String str) throws Exception {
    StringBuffer result = new StringBuffer();
    boolean inEscape = false;
    boolean isEscaped = false;
    int lastEscapeIndex = 0;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == '\u2029' || c == '\t' || c == ' ') {
            if (!isEscaped) {
                result.append(c);
            }
        } else if (c == '\\') {
            inEscape = true;
            isEscaped = true;
            lastEscapeIndex = i;
        } else {
            if (inEscape) {
                if (c == 'n') {
                    result.append('\n');
                } else if (c == 'r') {
                    result.append('\r');
                } else {
                    result.append(c);
                }
                inEscape = false;
                i++; // Skip next char since we processed the one before
                lastEscapeIndex = i; // Update last escape index
            } else {
                result.append(c);
            }
        }
    }

    return result.toString();
}

