private static String mapToString(Object value) {
    if (value instanceof String) {
        return (String) value;
    } else if (value instanceof Integer) {
        return Integer.toString((Integer) value);
    } else if (value instanceof Double) {
        return Double.toString((Double) value);
    } else if (value instanceof Boolean) {
        return ((Boolean) value).toString();
    } else if (value instanceof JsonArray) {
        return "[" + ((JsonArray) value).stream()
            .map(JsonObject::toString)
            .collect(Collectors.joining(", ")) + "]";
    } else if (value instanceof File) {
        return ((File) value).getAbsolutePath();
    } else if (value instanceof List) {
        return "[" + ((List<?>) value).stream()
            .map(mapToString)
            .collect(Collectors.joining(", ")) + "]";
    } else if (value instanceof Map) {
        return mapToJson((Map<?, ?>) value);
    } else {
        return "";
    }
}

private static String mapToJson(Map<?, ?> map) {
    JsonObjectBuilder builder = JsonObjectBuilder.create();
    for (Map.Entry<?, ?> entry : map.entrySet()) {
        builder.add(entry.getKey().toString(), mapToString(entry.getValue()));
    }
    return builder.build().toString();
}

