// Helper method to find the indices of connected components in the set tour
private int[] findConnectedComponents(Set<E> tour, Graph<V, E> graph) {
    int[] result = new int[tour.size()];
    boolean[] visited = new boolean[tour.size()];
    for (int i = 0; i < tour.size(); i++) {
        if (visited[i]) continue;
        ArrayList<Integer> component = new ArrayList<>();
        findConnectedComponentsFromVertex(tour, graph, i, visited, component);
        result[i] = component.size() - 1;
    }
    return result;
}

private void findConnectedComponentsFromVertex(Set<E> tour, Graph<V, E> graph, int vertex, boolean[] visited, ArrayList<Integer> component) {
    visited[vertex] = true;
    component.add(vertex);
    List<V> neighbors = graph.neighbors(vertex);
    for (V neighbor : neighbors) {
        int neighborIndex = tour.indexOf(graph.edge(neighbor, vertex));
        if (neighborIndex != -1 && !visited[neighborIndex]) {
            findConnectedComponentsFromVertex(tour, graph, neighborIndex, visited, component);
        }
    }
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    int[] componentTable = findConnectedComponents(tour, graph);
    GraphPath<V, E> path = new GraphPath<>();
    int components = new int[2];
    int componentSize = 0;
    for (int i=0; i<tour.size(); i++) {
        int j = graph.index(tour.get(i));
        if (componentTable[i] == componentTable[j]) components[++componentSize] = componentTable[i]; // component size
    }
    for (V v : tour) {
        int pos = graph.index(v);
        if (componentTable[pos] == components[1]) {
            path.add(v);
            continue;
        }
        boolean found = false;
        for (int v2 : tour) {
            int pos2 = graph.index(v2);
            if (componentTable[pos2] != components[1] && pos2 > pos) {
                path.add(v2);
                found = true;
                break;
            }
        }
        if (!found) {
            continue;
        }
        int diff = componentTable[pos2] - componentTable[pos];
        if (diff != 1) {
            for (int i = 0; i < diff; i++) {
                path.add(graph.in(v2));
            }
        }
    }
    return path;
}

/**
 * Transform from a Set representation to a graph path.
 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    GraphPath<V, E> path = new GraphPath<>(graph);
    Node<V> currentNode = path.addNode(graph.getVertex(tour.iterator().next().start()));
    int index = 0;

    for (E edge : tour) {
        Node<V> nextNode = path.addNode(graph.getVertex(edge.get(end())));
        path.addEdge(currentNode, nextNode, edge.getLabel());
        currentNode = nextNode;
        index++;
    }

    return path;
}

