public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel == 0) {
        for (int i = 0; i < bucketsByLabel.size(); i++) {
            bucketsByLabel.get(i).clear();
        }
        return;
    }

    List<Set<Integer>> tempBuckets = new ArrayList<>(bucketsByLabel);
    Set<Integer> newBuckets = new HashSet<>();
    for (int label : labels) {
        if (label == minLabel) {
            tempBuckets.remove(tempBuckets.indexOf(label));
            newBuckets.add(0);
        } else {
            newBuckets.add(label);
        }
    }
    bucketsByLabel.clear();
    bucketsByLabel.addAll(tempBuckets);
    for (int label : newBuckets) {
        bucketsByLabel.get(label).clear();
    }

    for (int i = 0; i < labels.size(); i++) {
        int destLabel = labels.get(i);
        List<Integer> srcBuckets = new ArrayList<>(tempBuckets);
        srcBuckets.remove(i);
        srcBuckets.add(0);
        Set<Integer> hashedBuckets = new HashSet<>();
        for (int srcLabel : srcBuckets) {
            hashedBuckets.add(bucketsByLabel.get(srcLabel).hashCode());
        }
        Set<Integer> destBuckets = new HashSet<>();
        for (int i = 0; i < labels.size(); i++) {
            if (i != destLabel && hashedBuckets.contains(bucketsByLabel.get(labels.get(i)).hashCode())) {
                destBuckets.add(labels.get(i));
            }
        }
        bucketsByLabel.clear();
        for (int srcLabel : srcBuckets) {
            bucketsByLabel.put(srcLabel, null);
        }
        if (destBuckets.isEmpty()) {
            break;
        } else {
            bucketsByLabel.put(0, new HashSet<>());
            for (int destLabel : destBuckets) {
                bucketsByLabel.get(0).addAll(bucketsByLabel.get(destLabel));
                bucketsByLabel.remove(destLabel);
            }
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minLabel value");
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    if (minLabel > 0) {
        for (Integer label : bucketsByLabel.remove(minLabel)) {
            bucketsByLabel.get(0).add(label);
        }
    }

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        labels.set(i, labels.get(i) - minLabel + 1);
    }
}

