public Pair<List<Integer>, Long> computeSuffixSum() {
    List<Integer> suffixSum = new ArrayList<>();
    suffixSum.add(total);

    OptionalDouble sum = bounds.stream().mapToLong(Integer::longValue).reduce(Long::sum);
    if (sum.isPresent()) {
        suffixSum.add(sum.getAsLong());
    }

    return Pair.of(suffixSum, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSums = new ArrayList<>();
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSums.add(bounds.get(i));
        totalSum += bounds.get(i);
    }

    return new Pair<>(suffixSums, totalSum);
}

