    private List<Integer> suffixSumList;

    public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        if (bounds == null || bounds.isEmpty()) {
            throw new IllegalArgumentException("Bounds list cannot be null or empty");
        }

        int sum = 0;
        suffixSumList = new ArrayList<>();
        for (int i = bounds.size() - 1; i >= 0; i--) {
            sum += bounds.get(i);
            suffixSumList.add(sum);
        }

        return new Pair<>(suffixSumList, (long) sum);
    }
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<>();
    long total = 0;
    for (Integer bound : bounds) {
        total += bound;
        suffixSum.add(total);
    }
    return Pair.of(suffixSum, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long total = 0;

    for (int i = n - 1; i >= 0; i--) {
        suffixSum.add(total);
        total += bounds.get(i);
    }

    return new Pair<>(suffixSum, total);
}

