public static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        if (prefix == null) {
            return true;
        }
        return false;
    }
    if (prefix == null) {
        return true;
    }
    int minLen = Math.min(str.length(), prefix.length());
    for (int i = 0; i < minLen; i++) {
        if (ignoreCase) {
            if (str.charAt(i) != prefix.charAt(i) && Character.toLowerCase(str.charAt(i)) != Character.toLowerCase(prefix.charAt(i))) {
                return false;
            }
        } else {
            if (str.charAt(i) != prefix.charAt(i)) {
                return false;
            }
        }
    }
    if (str.length() > prefix.length()) {
        char lastStrChar = str.charAt(minLen);
        if (ignoreCase) {
            return lastStrChar == prefix.charAt(minLen) && Character.toLowerCase(lastStrChar) == Character.toLowerCase(prefix.charAt(minLen));
        } else {
            return lastStrChar == prefix.charAt(minLen);
        }
    }
    return true;
}

