/**
 * Decoding a string to a string follow the Base64 regular.
 *
 * @param s The string to decode.
 * @return The decoded string.
 * @throws IllegalArgumentException if the input string is not properly encoded.
 */
public static String base64Decode(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string must not be null or empty.");
    }

    int length = s.length();
    if (length % 4 != 0) {
        throw new IllegalArgumentException("Input string must have a multiple of four characters.");
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i += 4) {
        int a = Base64ToInt(s.charAt(i));
        int b = Base64ToInt(s.charAt(i + 1));
        int c = Base64ToInt(s.charAt(i + 2));
        int d = Base64ToInt(s.charAt(i + 3));

        int value = (a << 18) | (b << 12) | (c << 6) | d;
        sb.append((char) (value >>> 16));
        sb.append((char) (value >>> 8));
        sb.append((char) value);
    }

    return sb.toString();
}

private static int Base64ToInt(char ch) {
    if (ch >= 'A' && ch <= 'Z') {
        return ch - 'A';
    } else if (ch >= 'a' && ch <= 'z') {
        return ch - 'a' + 26;
    } else if (ch >= '0' && ch <= '9') {
        return ch - '0' + 52;
    } else if (ch == '+') {
        return 62;
    } else if (ch == '/') {
        return 63;
    } else {
        throw new IllegalArgumentException("Invalid Base64 character: " + ch);
    }
}

