private void reverse(File[] arr, int start, int end) {
    if (start >= end) {
        return;
    }
    File temp = arr[start];
    arr[start] = arr[end];
    arr[end] = temp;
    reverse(arr, start+1, end-1);
}

private void addReverse(final File[] files) throws IOException {
    if (files == null || files.length == 0) {
        throw new IllegalArgumentException("Files array cannot be null or empty");
    }

    ArrayDeque<File> deque = new ArrayDeque<>();
    for (File file : files) {
        deque.addFirst(file);
    }

    File finalFile = deque.peekFirst();
    while (!deque.isEmpty()) {
        File duplicateFile = new File(finalFile.getParentFile(), finalFile.getName() + "_duplicate");
        if (duplicateFile.exists()) {
            int count = 1;
            duplicateFile = new File(finalFile.getParentFile(), finalFile.getName() + "_duplicate_" + count);
            while (duplicateFile.exists()) {
                count++;
                duplicateFile = new File(finalFile.getParentFile(), finalFile.getName() + "_duplicate_" + count);
            }
        }
        finalFile.renameTo(duplicateFile);
        Collections.rotate(deque, -1);
        finalFile = deque.peekFirst();
    }
}

