    if (lastDotIndex == -1) {
        return -1;
    }
    int firstSeparatorIndex = filename.indexOf("/", lastDotIndex + 1) != -1 ? filename.indexOf("/", lastDotIndex + 1) : filename.indexOf("\\\\", lastDotIndex + 1);
    if (firstSeparatorIndex != -1 && firstSeparatorIndex < lastDotIndex) {
