static public String toString(final char ch){
    if ((ch & 0xff80) == 0) {
        return " " + ch;

    } else if ((ch & 0xf800) == 0) {
        return "A" + ch;

    } else if ((ch & 0xf000) == 0) {
        return "B" + ch;

    } else {
        if (ch < 0x2000) {
            return "C" + ch;

        } else if (ch < 0x4000) {
            return "D" + ch;

        } else if (ch < 0x6000) {
            return "E" + ch;

        } else if (ch < 0x8000) {
            return "F" + ch;

        } else if (ch < 0xc000) {
            return "G" + ch;

        } else if (ch < 0xe000) {
            return "H" + ch;

        } else if (ch < 0xf000) {
            return "I" + ch;

        } else if (ch < 0xf800) {
            return "J" + ch;

        } else if (ch >= 0xf000 && ch < 0xffff) {
            return "K" + ch;

        } else {
            return "L" + ch;
        }
    }
}

