public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input. File and time ranges must not be null or empty.");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Open the file for reading
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");

        // Iterate through each line in the file
        while ((line = reader.readLine()) != null) {
            // Parse the line into components
            String[] parts = line.split(",");
            if (parts.length < 3) {
                throw new IllegalArgumentException("Invalid format in the file.");
            }

            String timestampStr = parts[0];
            String threadName = parts[1];
            String snapshotTimeStr = parts[2];

            // Parse timestamps
            long timestamp = dateFormat.parse(timestampStr).getTime();
            long snapshotTime = dateFormat.parse(snapshotTimeStr).getTime();

            // Validate the timestamps against the time ranges
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                    // Create a new ThreadSnapshot and add it to the list
                    ThreadSnapshot snapshot = new ThreadSnapshot(threadName, timestamp, snapshotTime);
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }

    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    FileReader reader = new FileReader(file);
    BufferedReader bufferedReader = new BufferedReader(reader);
    String line;
    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    while ((line = bufferedReader.readLine()) != null) {
        String[] fields = line.split(",");
        if (fields.length == 9) {
            long start = Long.parseLong(fields[0]);
            double cpuUsage = Double.parseDouble(fields[1]);
            double memoryUsage = Double.parseDouble(fields[2]);
            double gcTime = Double.parseDouble(fields[3]);
            double peakMemoryUsage = Double.parseDouble(fields[4]);
            double ioTime = Double.parseDouble(fields[5]);
            String pid = fields[6];
            String threadName = fields[7];
            long timestamp = dateFormat.parse(fields[8]).getTime();

            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    ThreadSnapshot snapshot = new ThreadSnapshot();
                    snapshot.setStartTime(start);
                    snapshot.setCpuUsage(cpuUsage);
                    snapshot.setMemoryUsage(memoryUsage);
                    snapshot.setGcTime(gcTime);
                    snapshot.setPeakMemoryUsage(peakMemoryUsage);
                    snapshot.setIoTime(ioTime);
                    snapshot.setPid(pid);
                    snapshot.setThreadName(threadName);
                    snapshot.setTimestamp(timestamp);
                    threadSnapshots.add(snapshot);
                }
            }
        }
    }
    bufferedReader.close();
    return threadSnapshots;
}

